from pathlib import Path
import sys, json, re, html, shutil, hashlib, os
sys.path.insert(0,str(Path(__file__).parent/'src'))
from content import OFFERS, FAQ, SOURCES

ROOT=Path(__file__).parent
DIST=ROOT/'dist'
A='/assets/'
PAGES={}
e=html.escape

def icon(name='arrow-right',cls=''):
 return f'<img class="icon {cls}" src="{A}icons/ui/{name}.svg" width="20" height="20" alt="" aria-hidden="true">'

def btn(text,url,kind='primary',extra=''):
 return f'<a class="button {kind}" href="{url}" {extra}><span>{text}</span>{icon("arrow-right")}</a>'

def badge(text='DEMO — SYNTHETIC DATA',kind='demo'):
 return f'<span class="badge {kind}">{text}</span>'

def sectionhead(kicker,title,copy='',link=''):
 return f'<div class="section-heading"><div><p class="eyebrow">{kicker}</p><h2>{title}</h2></div><div>{f"<p>{copy}</p>" if copy else ""}{link}</div></div>'

def figure(asset,alt,theme='',caption='Illustrative concept · Synthetic data',data=''):
 alt=re.sub('<[^>]+>',' ',alt)
 if not data and asset in ['landed-cost-bars','cost-waterfall']:
  data='<p>Canonical synthetic scenario: 1,000 units × $12 = $12,000. Invented rates A 4%, B 6%. Goods $12,000; duty $480 / $720; freight $600; insurance $80; broker fee $150. Included subtotal A $13,310 ($13.31 per unit), B $13,550 ($13.55 per unit). Difference $240, not savings. Other tariffs, AD/CVD, MPF/HMF, taxes, and valuation adjustments unassessed.</p>'
 if not data and asset=='tariff-change-line':
  data='<p>Simulated fixture change only. Invented rates: 4% on 01 and 02 Oct 2026, 5% on 03 Oct, and 6% on 04 Oct. This illustration is not an actual tariff history or live alert. A changed source opens a human review task.</p>'
 return f'<figure class="visual {theme}" data-reveal><img src="{A}visuals/{asset}.svg" alt="{e(alt)}" width="720" height="420" loading="lazy"><figcaption>{badge()}<span>{caption}</span>{f"<details class=visual-data><summary>Read the data</summary>{data}</details>" if data else ""}</figcaption></figure>'

def split(kicker,title,copy,asset,reverse=False,theme='',link='',data='',anchor=''):
 return f'<section class="section {theme}" {f"id={anchor}" if anchor else ""}><div class="container split {"reverse" if reverse else ""}"><div class="split-copy" data-reveal><p class="eyebrow">{kicker}</p><h2>{title}</h2><p>{copy}</p>{link}</div>{figure(asset,title,data=data)}</div></section>'

def cards(items):
 return '<div class="editorial-cards">'+''.join(f'<article class="editorial-card" data-reveal><span class="index">0{i+1}</span>{icon(v[0])}<h3>{v[1]}</h3><p>{v[2]}</p></article>' for i,v in enumerate(items))+'</div>'

def faqs(items=FAQ,title='A few useful questions.',kicker='Before the next step'):
 return '<section class="section faq-section"><div class="container faq-layout"><div data-reveal><p class="eyebrow">'+kicker+'</p><h2>'+title+'</h2><p>A clear boundary is part of a useful review.</p><a class="text-link" href="/faq">All questions '+icon()+'</a></div><div class="accordion">'+''.join(f'<details><summary>{q}{icon("plus")}</summary><p>{a}</p></details>' for q,a in items)+'</div></div></section>'

def cta(title='Start with one lane.\nLearn from ten SKUs.',copy='Review a permissioned sample with your importer and broker. Choose one offer as the first commercial test.',label='Discuss a scoped pilot',url='/request-pilot',dark=False):
 return f'<section class="cta-section {"ink" if dark else ""}"><div class="container cta-box"><div data-reveal><p class="eyebrow">A bounded next step</p><h2>{title.replace(chr(10),"<br>")}</h2><p>{copy}</p></div><div>{btn(label,url)}<span class="fineprint">Research-stage pilot · No checkout</span></div><img class="cta-fold" src="{A}logos/skudocket-mark-primary.svg" alt="" aria-hidden="true"></div></section>'

def offers_grid(compact=False):
 return '<div class="offer-grid">'+''.join(f'<article class="offer-card offer-{o["id"]}" data-reveal><div class="offer-meta"><span class="index">0{o["id"]}</span><span>Proposed module</span></div><div class="offer-visual"><img src="{A}visuals/{o["card"]}.svg" alt="Synthetic {e(o["name"].lower())} example" width="384" height="200" loading="lazy"><div class="offer-back"><strong>Inputs for review</strong>'+''.join(f'<p>{t}</p>' for t in o['inputs'])+f'</div>{badge()}</div><h3>{o["name"]}</h3><p>{o["intro"]}</p><button class="flip-trigger" data-flip aria-pressed="false" aria-label="Flip {e(o["name"])} illustration to inputs">{icon("rotate-ccw")}View inputs</button><a class="text-link stretch-link" href="/products/{o["slug"]}">Explore this offer {icon()}</a></article>' for o in OFFERS)+'</div>'

def workflow(interactive=False):
 items=[('Collect the evidence.','Connect SKU, supplier, invoice, and source versions.','workspace-relationships','collection'),('Review what is unresolved.','Compare alternatives. Keep holds and human decisions visible.','human-disposition','human-review'),('Assemble the broker packet.','Export the reviewed evidence, with open questions included.','broker-packet-provenance','handoff')]
 rows=[]
 for i,(title,copy,asset,anchor) in enumerate(items):
  action=f'<a class="workflow-step-link" href="#{anchor}">Inspect this step {icon("arrow-up-right")}</a>' if interactive else ''
  rows.append(f'<article data-reveal><span class="index">0{i+1}</span><img src="{A}visuals/{asset}.svg" alt="{title}" width="720" height="420" loading="lazy"><h3>{title}</h3><p>{copy}</p>{action}</article>')
 return '<div class="workflow-strip">'+''.join(rows)+'</div>'

def general_hero(kicker,title,copy,asset,layout='split',cta_label='Explore the demo',cta_url='/demo',extra='',dark=False):
 art= f'<img src="{A}{asset}" alt="{e(title.replace(chr(10)," "))} illustration" width="720" height="420">' if '/' in asset else f'<img src="{A}visuals/{asset}.svg" alt="Synthetic {e(title.replace(chr(10)," "))} diagram" width="720" height="420">'
 return f'<section class="page-hero hero-{layout} {"ink" if dark else ""}"><div class="container"><div class="hero-text"><p class="eyebrow">{kicker}</p><h1>{title.replace(chr(10),"<br>")}</h1><p class="lead">{copy}</p><div class="hero-actions">{btn(cta_label,cta_url)}{extra}</div></div><div class="hero-figure">{art}{badge()}<span class="hero-asset-note">Concept preview · Original illustration</span></div></div></section>'

def render_header():
 groups=[('Products',[('All five offers','/products')]+[(o['name'],'/products/'+o['slug']) for o in OFFERS]),('Workflow',[('How it works','/how-it-works'),('The workspace','/workspace'),('Controls & limits','/controls')]),('For teams',[('Import compliance teams','/for-importers'),('Customs brokers','/for-brokers')]),('Resources',[('Resource library','/resources'),('Sample dossier','/resources/sample-dossier'),('Method & sources','/resources/method-and-sources'),('FAQ','/faq')])]
 nav=''.join('<details class="nav-group"><summary>'+name+icon('chevron-down')+'</summary><div class="nav-dropdown">'+''.join(f'<a href="{url}">{label}{icon("arrow-up-right")}</a>' for label,url in links)+'</div></details>' for name,links in groups)
 return f'<a class="skip-link" href="#main">Skip to content</a><div class="site-status"><div class="container"><span><i></i>Research-stage concept</span><a href="/controls">Synthetic previews. Human review. {icon("arrow-up-right")}</a></div></div><header class="site-header"><div class="container nav-shell"><a class="brand" href="/" aria-label="SKUDocket home"><img src="{A}logos/skudocket-logo-primary.svg" alt="SKUDocket" width="172" height="32"></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="Open navigation">{icon("menu")}</button><nav id="main-nav" aria-label="Main navigation">{nav}<div class="nav-actions"><a class="preview-link" href="/sign-in">Sign in</a>{btn('Explore demo','/demo','small')}</div></nav></div></header>'

def render_footer():
 groups=[('Product',[('All offers','/products')]+[(o['name'],'/products/'+o['slug']) for o in OFFERS]),('Workflow',[('For importers','/for-importers'),('For brokers','/for-brokers'),('How it works','/how-it-works'),('Workspace','/workspace'),('Controls & limits','/controls')]),('Evaluate',[('Interactive demo','/demo'),('Ten-SKU pilot','/pilot'),('Test pricing','/pricing'),('Request a walkthrough','/request-demo'),('Research updates','/waitlist')]),('Company & resources',[('About SKUDocket','/about'),('Contact','/contact'),('Resources','/resources'),('Method & sources','/resources/method-and-sources'),('Questions','/faq')])]
 col=''.join('<div class="footer-col"><h3>'+n+'</h3>'+''.join(f'<a href="{u}">{t}</a>' for t,u in links)+'</div>' for n,links in groups)
 return f'<footer class="site-footer"><div class="container"><div class="footer-masthead"><div class="footer-identity"><a href="/" aria-label="SKUDocket home"><img src="{A}logos/skudocket-logo-reverse.svg" width="240" height="46" alt="SKUDocket"></a><span class="footer-note">US repeat-SKU import lane</span><span class="footer-status">Research-stage concept</span></div><div class="footer-invitation"><p class="eyebrow">The next broker conversation</p><h2>Put the evidence<br>on the desk.</h2><div class="footer-actions">{btn('Explore the demo','/demo','footer-demo')}<a class="footer-source-link" href="/resources/method-and-sources">Method &amp; sources {icon("arrow-up-right")}</a></div></div></div><nav class="footer-links" aria-label="Footer navigation">{col}</nav><div class="footer-utility"><div class="footer-social"><span>Company profiles</span><div class="social-icons"><button disabled aria-label="LinkedIn profile not yet supplied" title="Company profile not yet supplied"><img src="{A}icons/social/linkedin.svg" alt="LinkedIn" width="20" height="20"></button><button disabled aria-label="Crunchbase profile not yet supplied" title="Company profile not yet supplied"><img src="{A}icons/social/crunchbase.svg" alt="Crunchbase" width="20" height="20"></button></div><small>Coming later</small></div><a class="footer-contact" href="/contact">A question about the concept? {icon("arrow-up-right")}</a></div><div class="footer-bottom"><span>© 2026 SKUDocket · Concept preview</span><div><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/accessibility">Accessibility</a><button class="link-button" data-open="analytics">Privacy choices</button></div></div><p class="footer-disclosure">All product records, people, amounts, and outcomes are fictional. Suggested classifications are nonbinding. No customs filing, real screening, payments, or production integrations.</p></div></footer>'

def register(route,title,body,desc='',kind='marketing'):
 PAGES[route]=dict(title=title,body=body,desc=desc or title,kind=kind)

def home():
 hero=f'''<section class="home-hero"><div class="container hero-heading"><p class="eyebrow"><span class="tiny-rule"></span> An evidence desk for US importers</p><h1>Prepare repeat-SKU<br>import dossiers<br><em>for broker review.</em></h1><p class="lead">The facts, the gaps, and the reasoning behind your<br class="desktop-only"> next broker conversation. Together in one proposed workbench.</p><div class="hero-actions">{btn('Explore the demo','/demo')}{btn('Discuss a ten-SKU pilot','/pilot','secondary')}</div><p class="hero-note">Research-stage concept · No filing · Human authority retained</p></div><div class="harbor-stage"><img class="harbor-background" src="{A}illustrations/harbor-atlas.webp" alt="Original watercolor of an American harbor, cargo quay, and coastal bridge" width="1536" height="1024"><div class="hero-film" id="hero-film"><div class="film-top"><span>{icon('file-text')} HX-42 / Evidence dossier</span>{badge('CONCEPT PREVIEW','quiet')}</div><div class="film-view"><video id="hero-video" muted playsinline loop preload="none" poster="{A}video/hero-poster.jpg" aria-label="Synthetic evidence-to-review product animation" aria-describedby="film-transcript"><source src="{A}video/skudocket-hero.mp4" type="video/mp4"></video><div class="film-fallback">{figure('classification-comparison','Two provisional classification rationales with source evidence')}</div></div><div class="film-bottom"><div class="film-stages" aria-label="Product film chapters"><button data-seek="1.8" aria-label="Show evidence chapter" aria-pressed="false">01 Evidence</button><button data-seek="5.4" aria-label="Show rationales chapter" aria-pressed="false">02 Rationales</button><button data-seek="8.8" aria-label="Show holds chapter" aria-pressed="false">03 Holds</button><button data-seek="12.5" aria-label="Show human review chapter" aria-pressed="false">04 Review</button><button data-seek="16" aria-label="Show packet draft chapter" aria-pressed="false">05 Packet</button></div><button id="film-toggle" class="film-control" aria-label="Play product animation">{icon('play')}<span>Play the story</span></button></div></div><p class="harbor-caption">One recurring SKU. Multiple suppliers. An evidence trail worth reviewing.</p></div><details class="film-transcript container" id="film-transcript"><summary>Read the animation transcript</summary><p>A synthetic SKU dossier collects specifications, an invoice, and a prior-entry reference. Two unassigned classification hypotheses appear. The origin affidavit is missing and a similar-name screening hit is unresolved. The sequence pauses on a human review prompt. A draft broker packet keeps the open issues visible. Nothing is cleared, sent, or filed by the animation.</p></details></section>'''
 qualifier=f'''<section class="section qualifier"><div class="container"><div class="qualifier-top" data-reveal><p class="eyebrow">For the importer of record</p><h2>Repeat goods.<br>New questions.</h2><p>For US importers managing recurring SKUs across several suppliers and a customs broker. The entry may be familiar. The evidence still deserves a review.</p></div><div class="artifact-line"><div class="artifact">{icon('table-2')}<span>Tariff master</span><small>Proposed classification</small></div><div class="artifact">{icon('files')}<span>Supplier evidence</span><small>Product & origin facts</small></div><div class="artifact">{icon('messages-square')}<span>Broker questions</span><small>What needs another look</small></div><div class="artifact sku-artifact"><span>HX-42</span><small>A single reviewable record</small>{badge()}</div></div><div class="workflow-question"><p>Across your last <strong>10 repeat-SKU entries</strong>, how many needed another document or broker clarification?</p><a class="text-link" href="/for-importers">Explore the importer workflow {icon()}</a></div></div></section>'''
 evidence=split('01 / The evidence spread','Two rationales.<br>The same product facts.','For fictional SKU HX-42, construction may suggest one interpretation; the assembly’s full function may suggest another. See both assumptions, and the missing fact that would help the broker assess them.','classification-comparison',link=btn('Compare the rationales','/products/classification-dossiers','secondary')+'<a class="source-link" href="/resources/method-and-sources">Nonbinding suggestions · Official guidance & sources</a>')
 five='<section class="section offers-section"><div class="container">'+sectionhead('02 / Five independent offers','Choose the job<br>you need to review.','Each proposed module tests a distinct recurring task. Start with one; a bundle remains a question for buyers.', '<a class="text-link" href="/products">Compare all offers '+icon()+'</a>')+offers_grid()+'</div></section>'
 flow='<section class="section workflow-section"><div class="container">'+sectionhead('03 / A reviewed workflow','Collect. Question. Assemble.','A proposed evidence loop with named reviewers and reversible decisions. Nothing disappears behind a single “compliant” badge.')+workflow()+'<div class="center-actions">'+btn('See how the review works','/how-it-works','secondary')+'</div></div></section>'
 demo=f'''<section class="section demo-chapter"><div class="container">{sectionhead('04 / Inside a fictional record','A real question.<br>A synthetic example.','Open HX-42. Compare assumptions, inspect the origin gap, and review a similar-name match before assembling the packet.',btn('Open the workbench','/demo/skus/hx-42','secondary'))}<div class="home-workbench"><div class="mini-queue"><div class="mini-queue-head">Alder Import Co {badge()}</div><div class="mini-row"><b>HX-42</b><span class="status held">Held</span><small>Harborside Works</small></div><div class="mini-row"><b>HX-43</b><span class="status pending">Pending</span><small>Harborside Works</small></div><div class="mini-row"><b>BR-18</b><span class="status collected">Collected</span><small>North Quay Components</small></div><div class="mini-row"><b>FT-33</b><span class="status rejected">Rejected</span><small>Function contradicts proposal</small></div><a href="/demo/skus" class="text-link">All ten example SKUs {icon()}</a></div><div class="mini-record"><div class="record-meta">EN-104 · Stainless fastener assembly <span>Fixture as of 01 Oct 2026</span></div><h3>HX-42 needs another look.</h3><div class="mini-hypotheses"><div><span>Rationale A</span><b>Component construction</b><small>Provisional · HTS unassigned</small></div><div><span>Rationale B</span><b>Assembly function</b><small>Provisional · HTS unassigned</small></div></div><div class="alert warning">{icon('circle-alert')}<div><b>Origin affidavit missing</b><span>ORG-HX42-v1 · Maya Chen · Due 03 Oct</span></div></div><div class="alert info">{icon('scan-search')}<div><b>Potential screening hit · unresolved</b><span>Simulated list · Human disposition required</span></div></div><div class="mini-record-foot"><span>Broker reviewer / Noah Reed</span><a href="/demo/skus/hx-42">Review the blockers {icon()}</a></div></div></div></div></section>'''
 controls=f'''<section class="section ink controls-chapter"><div class="container">{sectionhead('05 / Authority stays visible','Prepared is a state.<br>Approved is a decision.','A dossier organizes evidence. It does not replace importer responsibility or professional judgment.')}<div class="control-pairs"><article>{icon('user-check')}<h3>Human disposition</h3><p>A potential match stays unresolved until a reviewer examines identifiers and records a reason.</p></article><article>{icon('git-branch')}<h3>Reversible proposals</h3><p>Reject or revise an assumption with evidence. The history keeps the alternative and the reason.</p></article><article>{icon('calendar-days')}<h3>Dated sources</h3><p>See versions, dates, and coverage. Stale data opens a review task rather than a silent update.</p></article><article>{icon('ban')}<h3>A clear stop</h3><p>No filing, funds transfer, external messages, or ERP and bank writes. Export is a local packet.</p></article></div>{btn('Explore controls & limits','/controls','secondary')}</div></section>'''
 pilot=f'''<section class="section pilot-home"><div class="container split"><div data-reveal><p class="eyebrow">06 / Validate the repeat job</p><h2>Ten historical SKUs.<br>One scoped question.</h2><p>Importer and broker review the same lane against prior entries. Count disagreements, evidence gaps, and preparation rework. Ask whether the broker would incorporate the dossier.</p><p class="price-hypothesis"><span>Hypothetical test price</span><strong>$3,000</strong> for a ten-SKU pilot</p><p class="fineprint">Recurring hypothesis: $750–$2,500 / month per repeat lane. No active offer, checkout, or acceptance demonstrated.</p>{btn('See the pilot scope','/pilot','secondary')}</div>{figure('pilot-scorecard','A pilot evaluation scorecard with outcomes intentionally unmeasured')}</div></section>'''
 wait=f'''<section class="section waitlist-home"><div class="container split"><div data-reveal><p class="eyebrow">07 / Stay close to the research</p><h2>Useful questions<br>come before scale.</h2><p>Explore a walkthrough or prepare an updates request. The ungated demo is available without giving us your email.</p><div class="form-intro-art"><img src="{A}visuals/waitlist-consent.svg" alt="A purpose-limited research updates concept" loading="lazy" width="720" height="420"></div></div>{form('waitlist',compact=True)}</div></section>'''
 return hero+qualifier+evidence+five+flow+demo+controls+pilot+wait+faqs(FAQ[:4])+cta()

def product(o):
 h=general_hero(f'Offer 0{o["id"]} / Proposed module · {o["label"]}',o['title'],o['intro'],o['asset'],layout=['spread','folio','identities','ledger','manifest'][o['id']-1],cta_label=['Compare HX-42 rationales','Inspect missing proof','Review the example match','Compare scenarios','Preview the sample packet'][o['id']-1],cta_url='/demo/skus/hx-42?tab='+['classification','origin','screening','cost','packet'][o['id']-1],extra=btn('Discuss this offer',f'/request-pilot?offer={o["id"]}','secondary'))
 h+='<section class="section"><div class="container">'+sectionhead('The recurring trigger',o['trigger'],o['problem'])+'<div class="io-grid"><article><p class="eyebrow">Required inputs</p><ul>'+''.join('<li>'+icon('file-text')+t+'</li>' for t in o['inputs'])+'</ul></article><article><p class="eyebrow">Prepared output</p><ul>'+''.join('<li>'+icon('file-check-2')+t+'</li>' for t in o['outputs'])+'</ul></article></div></div></section>'
 h+='<section class="section paper"><div class="container">'+sectionhead('A specific review sequence','Make each step inspectable.')+cards([(ico,t,o['stepcopy'][i]) for i,(ico,t) in enumerate(zip(['files','scan-search','user-check'],o['steps']))])+'</div></section>'
 for i,(t,c,a) in enumerate(o['sections']):h+=split(f'0{i+1} / Inside the proposed module',t,c,a,reverse=i%2==1,theme='soft-section' if i%2 else '',link='<a class="text-link" href="/demo/skus/hx-42?tab='+['classification','origin','screening','cost','packet'][o['id']-1]+'">Inspect the synthetic example '+icon()+'</a>')
 h+=f'<section class="section ink"><div class="container limit-grid"><div><p class="eyebrow">Controls & scope</p><h2>What the output<br>can—and cannot—settle.</h2></div><div><p>{o["limit"]}</p><p><strong>Expected reviewer:</strong> importer compliance owner and customs broker; counsel where the question requires it.</p><a href="/controls" class="text-link">Review the limits {icon()}</a></div></div></section>'
 h+=split('The pilot question','Would this help the<br>broker prepare the entry?',o['metric'],'pilot-scorecard',link=btn('Discuss offer '+str(o['id']),'/request-pilot?offer='+str(o['id']),'secondary'))
 h+=faqs(o['faq'],title='Questions for this offer.')
 h+='<section class="section related"><div class="container">'+sectionhead('Related, independently tested offers','Continue the evidence trail.')+'<div class="related-links">'+''.join(f'<a href="/products/{r["slug"]}"><span>0{r["id"]}</span><h3>{r["name"]}</h3>{icon()}</a>' for r in OFFERS if r!=o)+'</div></div></section>'
 return h+cta(label='Discuss this offer',url='/request-pilot?offer='+str(o['id']))

def field(label,name,typ='text',options=None,required=False,autocomplete='',help=''):
 rid='field-'+name
 if options:
  control=f'<select id="{rid}" name="{name}" {"required" if required else ""}><option value="">Choose an option</option>'+''.join(f'<option value="{e(str(val))}">{e(text)}</option>' for val,text in options)+'</select>'
 elif typ=='textarea':control=f'<textarea id="{rid}" name="{name}" rows="3" maxlength="500"></textarea>'
 else:control=f'<input id="{rid}" name="{name}" type="{typ}" {"required" if required else ""} {f"autocomplete={autocomplete}" if autocomplete else ""} maxlength="120">'
 return f'<div class="field"><label for="{rid}">{label}{" <span aria-hidden=true>*</span>" if required else ""}</label>{control}{f"<small>{help}</small>" if help else ""}<span class="field-error" id="error-{name}"></span></div>'

def form(kind='demo',compact=False):
 title={'waitlist':'Prepare an updates request','demo':'Plan a walkthrough','pilot':'Define your repeat lane','contact':'Prepare an inquiry'}[kind]
 s=f'<form class="inquiry-form" data-form="{kind}" novalidate><fieldset disabled><div class="form-header"><p class="eyebrow">Inquiry preview</p><h3>{title}</h3></div><p class="form-status-note">This preview does not send or store your details. You can review and download the request.</p>'
 s+='<div class="form-fields">'+field('Work email','email','email',required=True,autocomplete='email')+field('Company','company',required=True,autocomplete='organization')+field('Your role','role',options=[('importer','Importer compliance lead'),('broker','Customs broker'),('forwarder','Freight forwarder'),('integrator','ERP / e-commerce integrator'),('other','Other')],required=True)
 if kind!='waitlist':
  s+=field('Name','name',autocomplete='name')
  s+=field('Primary offer of interest','offer',options=[(str(o['id']),o['name']) for o in OFFERS],required=kind=='pilot')
 if kind=='pilot':
  s+=field('Recurring SKUs in this lane','sku_band',options=[('1-10','1–10'),('11-50','11–50'),('51-250','51–250'),('250+','More than 250')],required=True)
  s+=field('Broker participation','broker_status',options=[('identified','Broker identified, not yet asked'),('interested','Broker interested in reviewing'),('confirmed','Participation confirmed separately'),('unknown','Not discussed')],required=True)
  s+='<details class="optional-fields"><summary>Add optional scope details '+icon('plus')+'</summary>'+field('Lane summary','lane',help='Country of origin and US destination only. No shipment or customer identifiers.')+field('Entry volume','volume_band',options=[('1-10','1–10 entries / month'),('11-50','11–50 entries / month'),('50+','More than 50 / month'),('unknown','Not yet measured')])+field('Pilot budget discussion','budget_status',options=[('unconfirmed','Unconfirmed'),('owner','Budget owner identified'),('discussion','Budget discussion possible'),('considered','$3,000 hypothesis considered')])+field('Permission for future sample review','permission_status',options=[('not-discussed','Not discussed'),('possible','Permission may be possible'),('separately-granted','Permission granted separately')])+'</details>'
 if kind=='contact':s+=field('Inquiry topic','topic',options=[('general','General question'),('broker','Broker participation'),('privacy','Privacy / deletion'),('accessibility','Accessibility feedback')],required=True)
 if kind not in ['waitlist']:
  s+=field('Your question','question','textarea',help='Please do not include invoices, real SKU records, financial information, or sensitive personal details.')
 s+='</div>'
 if kind!='waitlist':s+='<label class="checkbox"><input type="checkbox" name="contact_consent" required><span>I agree to the use of these details to respond about the requested research-stage walkthrough or pilot. I understand this is not an operating customs-filing service.</span></label>'
 s+=f'<label class="checkbox"><input type="checkbox" name="updates_consent" {"required" if kind=="waitlist" else ""}><span>Email me occasional SKUDocket research and pilot updates. I can unsubscribe.</span></label>'
