def legal_pages():
 legal=[('/privacy','Privacy in this preview','Data has a purpose.\nA preview has a boundary.','privacy-flow',[
 ('What this site processes','The product demo contains synthetic records only. Your review actions may be retained in session storage in this browser tab so you can move between demo pages. Resetting the demo removes that synthetic progress.'),
 ('Inquiry forms','The forms validate and preview what you enter. They do not send or store your email, company, name, or question. An optional download creates a file on your device; clear the fields when finished.'),
 ('Optional interaction diagnostics','Diagnostics are off unless you opt in through Privacy choices. An allowlisted event log stays in browser session storage and is not transmitted. No email, company name, raw case data, financial record, or free-text field goes into that log. You can clear it at any time.'),
 ('Hosting and external references','This website is hosted on Sites as a public concept preview. The hosting service handles requests under its own policies. Official-source links open third-party pages; their privacy practices apply there. Fonts, original artwork, and product assets are served with this website rather than fetched from font or tracking CDNs.'),
 ('Before live collection','A future inquiry service needs an identified operator, processors, retention period, consent records, unsubscribe mechanism, and working deletion contact. None is claimed to be active in this preview.'),
 ('Your controls','Use Privacy choices to switch off and clear diagnostics. Use Reset demo to erase synthetic progress. Clear inquiry fields or close the page; the forms have no stored inquiry record to delete. The contact page’s privacy topic is an inquiry preview until a live operator route is configured.')]),
 ('/terms','Preview terms and scope','A review artifact.\nA clearly bounded purpose.','terms-boundary',[
 ('Research-stage status','SKUDocket is a concept and website preview, not an operating customs-filing service. All product records, organizations, people, invoices, amounts, and outcomes are fictional.'),
 ('Informational use','The preview explains a proposed evidence-preparation workflow. Suggested classification reasoning is nonbinding. It is not legal advice, a customs ruling, sanctions clearance, origin certification, eligibility decision, or a guaranteed duty quote.'),
 ('Professional responsibility','Importer-of-record reasonable-care responsibility remains with the importer. Broker, counsel, and government authority are not replaced by a software suggestion, a prior entry, or packet approval.'),
 ('Unavailable actions','The preview cannot submit a customs entry, send messages to a broker or supplier, transfer funds, execute a government determination, or write to ERP and bank systems. A local synthetic PDF download is not transmission or filing.'),
 ('Hypothetical commercial terms','The $3,000 ten-SKU pilot and $750–$2,500 monthly repeat-lane range are test hypotheses. They are not active offers, subscriptions, accepted prices, guaranteed outcomes, or evidence of revenue.'),
 ('Sources and intellectual property','Official guidance is linked to its original publisher. The original SKUDocket artwork and UI explain this concept; third-party reference sites and social marks are not partners or endorsements. Final legal terms and company identity require operator and counsel review before a live service.')]),
 ('/accessibility','Accessibility','A clear path\nthrough the evidence.','accessibility-focus',[
 ('Keyboard and focus','Navigation groups, forms, dialogs, demo tabs, and review actions support keyboard use. A Skip to content link appears on focus. Dialogs close with Escape and return focus to the control that opened them.'),
 ('Readable information','Text uses contrasting colors and visible labels. Statuses include words as well as color. Classification alternatives stack on narrow screens; evidence details open in a readable sheet.'),
 ('Motion choices','The product film has a pause control. With reduced motion enabled, the complete poster is shown, and reveals, flips, and shutters become immediate state changes. No review decision depends on watching an animation.'),
 ('Charts and diagrams','Synthetic figures have descriptive alternatives. Interactive cost and queue charts include equivalent values in text or a data table. The film has a written transcript.'),
 ('Forms and errors','Controls have visible labels, required indications, and field-specific errors. Consent checkboxes start unchecked. Errors preserve entered values.'),
 ('Feedback and limits','This preview has been checked at desktop and mobile widths with keyboard interaction. It is not represented as independently certified accessibility compliance. Prepare feedback on the contact page with the Accessibility topic; the form does not send until an operator service is connected.')])]
 for route,title,h,asset,sections in legal:
  p=general_hero('Website preview / Information',h,'Clear scope, visible controls, and a way to inspect what the preview does.',asset,'compact',cta_label='Explore the controls',cta_url='/controls')
  p+='<section class="section legal-section"><div class="container legal-layout"><aside aria-label="On this page"><p class="eyebrow">On this page</p>'+''.join(f'<a href="#legal-{i}">{t}</a>' for i,(t,c) in enumerate(sections))+'</aside><div><p class="fineprint">Preview notice · 13 October 2026</p>'+''.join(f'<article id="legal-{i}"><h2>{t}</h2><p>{c}</p></article>' for i,(t,c) in enumerate(sections))+'</div></div></section>'
  if route=='/privacy':p+='<div class="container legal-actions"><button class="button secondary" data-open="analytics">Privacy choices '+icon('shield-check')+'</button><button class="button secondary" data-reset-demo>Reset synthetic progress '+icon('rotate-ccw')+'</button></div>'
  register(route,title,p)

def demo_pages():
 p=general_hero('Interactive demo / Synthetic data','Follow one SKU\nthrough the questions.','A fictional importer, supplier, and broker. A deterministic evidence loop you can inspect, revise, and reset.','demo-orientation','guided',cta_label='Open the ten-SKU queue',cta_url='/demo/skus',extra=btn('Start with HX-42','/demo/skus/hx-42','secondary'))
 p+='<section class="section"><div class="container">'+sectionhead('The example story','Alder Import Co.<br>SKU HX-42.','The stainless fastener assembly has two provisional rationales, missing origin proof, and a similar-name screening match. Fixture as of 01 Oct 2026.')+workflow()+'</div></section>'
 p+='<section class="section paper"><div class="container demo-path"><div><p class="eyebrow">A clickable review path</p><h2>See where<br>the work stops.</h2><p>No account needed. No real send, filing, payment, or system write is connected.</p>'+btn('Start the guided record','/demo/skus/hx-42')+'</div><ol>'+''.join('<li><span>0'+str(i+1)+'</span><div><h3>'+t+'</h3><p>'+c+'</p></div></li>' for i,(t,c) in enumerate([('Compare the alternatives','Read the source facts and the unsupported assumption. Try an edit and its reversal.'),('Inspect the origin hold','Load a synthetic response, then explicitly review it for its stated purpose.'),('Disposition the potential match','Compare fictional identifiers and addresses; require a reasoned human decision.'),('Review the packet','Record the broker’s rejection, working hypothesis, and remaining question. Then export locally.')]))+'</ol></div></section>'+split('An honest edge case','A rejected proposal<br>is part of the queue.','FT-33 contradicts its proposed product function. RD-11 uses a stale tariff fixture. These records keep exceptions visible rather than imply a successful outcome for every recommendation.','demo-queue')+cta()
 register('/demo','Interactive synthetic demo',p)
 shellstart=f'<section class="demo-shell"><div class="container"><div class="demo-topbar"><a href="/demo">{icon("arrow-left")}Demo overview</a><div>{badge()}{badge("CONCEPT PREVIEW","quiet")}</div><button class="button micro secondary" data-reset-demo>{icon("rotate-ccw")}Reset demo</button></div>'
 p=shellstart+'<div class="workbench-heading"><div><p class="eyebrow">Alder Import Co / Canada → US / Fictional lane</p><h1>Repeat-SKU review queue</h1><p>10 synthetic records · Snapshot 02 Oct 2026, 09:00 UTC</p></div><a class="text-link" href="/demo/skus/hx-42">Open HX-42 '+icon()+'</a></div><div id="queue-overview"></div><div class="queue-controls"><div class="field"><label for="queue-search">Find a SKU or supplier</label><div class="search-input">'+icon('search')+'<input id="queue-search" type="search" placeholder="Search the synthetic queue"></div></div><div class="field"><label for="queue-filter">Review state</label><select id="queue-filter"><option value="all">All states</option><option>Held</option><option>Pending review</option><option>Evidence collected</option><option>Broker review</option><option>Exported</option><option>Rejected proposal</option></select></div><span id="queue-count" role="status"></span></div><div id="queue-table"></div><div class="demo-boundary">'+icon('ban')+'<p>Every record is fictional. Prepared, reviewed, and exported are workflow states. No government approval, filing, or clearance is implied.</p></div></div></section>'
 register('/demo/skus','Synthetic review queue',p,kind='queue')
 p=shellstart+'<div class="breadcrumbs"><a href="/demo/skus">Review queue</a>'+icon('chevron-right')+'<span>HX-42 / EN-104</span></div><div class="workbench-heading"><div><p class="eyebrow">Harborside Works / Fictional supplier</p><h1>HX-42</h1><p>Stainless fastener assembly · Alder Import Co</p></div><div class="record-owner"><span>Owner / Maya Chen</span><span>Reviewer / Noah Reed <small>(simulated)</small></span><span>Next action due 03 Oct 2026, 16:00 UTC</span></div></div><div id="record-summary"></div><div class="workbench-layout"><aside class="workbench-sidebar"><p class="eyebrow">Evidence record</p><div class="workbench-tabs" role="tablist" aria-label="HX-42 review areas" aria-orientation="vertical">'+''.join(f'<button role="tab" id="tab-{key}" aria-selected="{str(i==0).lower()}" aria-controls="review-panel" data-tab="{key}" tabindex="{0 if i==0 else -1}">{icon(ico)}<span>{t}</span><small>0{i+1}</small></button>' for i,(key,t,ico) in enumerate([('classification','Classification','git-branch'),('origin','Origin evidence','file-search'),('screening','Screening review','scan-search'),('cost','Landed cost','calculator'),('packet','Broker review','clipboard-check')]))+'</div><div class="source-stamp"><span class="eyebrow">Fixture as of</span><b>01 Oct 2026</b><p>Simulated tariff and list data. No live feed.</p><a href="/resources/method-and-sources">Method & sources '+icon('arrow-up-right')+'</a></div></aside><div><div id="review-panel" role="tabpanel" tabindex="0" aria-labelledby="tab-classification"></div><div class="record-history"><details><summary>Review & revision history '+icon('chevron-down')+'</summary><div id="review-history"></div></details></div></div></div><div class="demo-boundary">'+icon('ban')+'<p>External actions are unavailable. This workbench cannot send messages, file entries, transfer funds, or write to ERP and bank systems.</p></div></div></section>'
 register('/demo/skus/hx-42','HX-42 synthetic dossier',p,kind='record')
 p=shellstart+'<div class="breadcrumbs"><a href="/demo/skus">Review queue</a>'+icon('chevron-right')+'<a href="/demo/skus/hx-42?tab=packet">HX-42</a>'+icon('chevron-right')+'<span>DKT-HX42-v1</span></div><div id="packet-view"><article class="packet-cover">'+badge()+'<h1>Broker-review dossier.</h1><h3>HX-42 / EN-104</h3><p>Complete the synthetic origin, screening, and broker-review steps before the local illustrative export.</p>'+btn('Review the blockers','/demo/skus/hx-42?tab=packet','secondary')+'</article></div></div></section>'
 register('/demo/packets/dkt-hx42-v1','Synthetic broker packet',p,kind='packet')

def dialogs():
 return f'''<dialog class="evidence-dialog" id="evidence-dialog" aria-labelledby="evidence-title"><div class="dialog-head"><div>{badge()}<h2 id="evidence-title">Evidence details</h2></div><button class="icon-button" data-close aria-label="Close evidence details">{icon('x')}</button></div><div id="evidence-body"></div></dialog><dialog class="privacy-dialog" id="analytics-dialog" aria-labelledby="analytics-title"><div class="dialog-head"><div><p class="eyebrow">Privacy choices</p><h2 id="analytics-title">Keep diagnostics local.</h2></div><button class="icon-button" data-close aria-label="Close privacy choices">{icon('x')}</button></div><p>Optional interaction diagnostics stay in this browser session. No form details or raw product records are recorded, and nothing is transmitted to an analytics provider.</p><label class="checkbox"><input type="checkbox" id="analytics-opt-in"><span>Allow session-local interaction diagnostics</span></label><div class="diagnostics-actions"><button class="button secondary" id="clear-analytics">Clear event log</button><button class="button secondary" id="download-analytics">Download local event log</button></div><p class="fineprint">Demo events describe synthetic interaction only. They do not establish qualified demand, a purchase, or a paid pilot.</p><p id="analytics-status" role="status"></p><a class="text-link" href="/privacy">Read the preview notice {icon()}</a></dialog><div id="toast" class="toast" role="status" aria-live="polite"></div>'''

def build():
 manifest=ROOT/'.openai/hosting.json'
 m=json.loads(manifest.read_text());m['static']={'directory':'dist'};manifest.write_text(json.dumps(m,indent=2)+'\n')
 css_version=hashlib.sha256((ROOT/'src/site.css').read_bytes()).hexdigest()[:12]
 js_version=hashlib.sha256((ROOT/'src/app.js').read_bytes()).hexdigest()[:12]
 register('/','Prepare repeat-SKU import dossiers for broker review',home(),'A research-stage evidence desk for US importers and customs brokers. Explore five proposed offers and a synthetic review workbench.')
 supporting_pages();resources_pages();company_pages();legal_pages();demo_pages()
 for route,p in PAGES.items():
  path=DIST/route.strip('/')/'index.html' if route!='/' else DIST/'index.html'
  path.parent.mkdir(parents=True,exist_ok=True)
  site_url=os.getenv('SITE_URL','').rstrip('/')
  canonical=site_url+('' if route=='/' else route) if site_url else ''
  canonical_meta=f'<link rel="canonical" href="{e(canonical)}"><meta property="og:url" content="{e(canonical)}"><meta property="og:image" content="{e(site_url)}/assets/video/hero-poster.jpg">' if site_url else ''
  head=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(p['title'])} — SKUDocket</title><meta name="description" content="{e(p['desc'])}"><meta name="theme-color" content="#FAF7EF"><meta name="robots" content="noindex,nofollow">{canonical_meta}<meta property="og:title" content="{e(p['title'])} — SKUDocket"><meta property="og:description" content="{e(p['desc'])}"><meta property="og:type" content="website"><link rel="icon" type="image/svg+xml" href="{A}logos/favicon.svg"><link rel="icon" href="{A}logos/favicon.ico"><link rel="apple-touch-icon" href="{A}logos/apple-touch-icon.png"><link rel="preload" href="{A}fonts/SourceSerif4-Roman.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="{A}fonts/PublicSans-Roman.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="{A}tokens.css"><link rel="stylesheet" href="{A}site.css?v={css_version}"><script src="{A}app.js?v={js_version}" defer></script></head><body data-page="{p['kind']}" data-route="{route}">'''
  path.write_text((head+render_header()+'<main id="main">'+p['body']+'</main>'+render_footer()+dialogs()+'</body></html>').replace('<summary>','<summary role="button" aria-expanded="false">'))
 shutil.copy(ROOT/'src/site.css',DIST/'assets/site.css');shutil.copy(ROOT/'src/app.js',DIST/'assets/app.js')
 (DIST/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found — SKUDocket</title><link rel="stylesheet" href="/assets/tokens.css"><link rel="stylesheet" href="/assets/site.css"><main class="container section"><p class="eyebrow">SKUDocket</p><h1>This record<br>is not here.</h1><p>The address may have changed. Return to the evidence desk.</p>'+btn('Back to home','/')+'</main></html>')
 (DIST/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
 (ROOT/'route-manifest.json').write_text(json.dumps([{'route':r,'title':p['title'],'kind':p['kind']} for r,p in PAGES.items()],indent=2)+'\n')
 print(f'Built {len(PAGES)} routes in {DIST}')

if __name__=='__main__':build()
